// TEMPORARY capture endpoint — writes a per-tooth PNG into public/teeth/<fdi>.png.
// Used by /tooth-capture. Safe to delete after captures are generated.
import { writeFile, mkdir } from "node:fs/promises";
import path from "node:path";

export async function POST(req) {
  try {
    const { fdi, dataUrl } = await req.json();
    if (!fdi || !dataUrl || !/^\d{2}$/.test(String(fdi))) {
      return Response.json({ ok: false, error: "bad input" }, { status: 400 });
    }
    const b64 = String(dataUrl).replace(/^data:image\/png;base64,/, "");
    const dir = path.join(process.cwd(), "public", "teeth");
    await mkdir(dir, { recursive: true });
    await writeFile(path.join(dir, `${fdi}.png`), Buffer.from(b64, "base64"));
    return Response.json({ ok: true, fdi });
  } catch (e) {
    return Response.json({ ok: false, error: String(e) }, { status: 500 });
  }
}
